files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.heart {
  width: 40%;
  padding: 20px;
  fill: black;
  cursor: pointer;
}

.heart:hover {
  border-radius: 20px;
  outline: 4px solid black;
}

.is-liked:hover {
  border-radius: 20px;
  outline: 4px solid red;
}
.is-liked {
  fill: red;
}
